/**
 * Calculate the Levenshtein distance between two strings.
 * @param {string} s1
 * @param {string} s2
 * @returns {number}
 */
function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;

  // Create a (m+1) x (n+1) matrix
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (s1[i - 1] === s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1];
      } else {
        dp[i][j] = 1 + Math.min(
          dp[i - 1][j],      // deletion
          dp[i][j - 1],      // insertion
          dp[i - 1][j - 1]   // substitution
        );
      }
    }
  }

  return dp[m][n];
}

/**
 * Create a debug helper for KnockoutJS binding errors.
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} - A debug helper object
 */
function createDebugHelper(viewModel) {
  const availableProps = Object.keys(viewModel).sort();

  /**
   * Diagnose a missing property.
   * @param {string} propertyName - The name of the property that failed to bind
   * @returns {Object} - Diagnosis result
   */
  function diagnoseMissingProperty(propertyName) {
    let suggestion = null;

    let minDistance = Infinity;
    let closestMatch = null;

    for (const prop of availableProps) {
      if (prop === propertyName) {
        // Property exists, no need for suggestion
        suggestion = null;
        minDistance = 0;
        break;
      }

      const dist = levenshteinDistance(propertyName, prop);

      if (dist <= 3) {
        if (dist < minDistance) {
          minDistance = dist;
          closestMatch = prop;
        } else if (dist === minDistance) {
          // If tie, pick alphabetically first
          if (prop < closestMatch) {
            closestMatch = prop;
          }
        }
      }
    }

    if (minDistance <= 3) {
      suggestion = closestMatch;
    } else {
      suggestion = null;
    }

    return {
      error: true,
      missingProperty: propertyName,
      availableProperties: availableProps,
      suggestion: suggestion
    };
  }

  return {
    diagnoseMissingProperty: diagnoseMissingProperty
  };
}

module.exports = {
  createDebugHelper: createDebugHelper,
  diagnoseMissingProperty: diagnoseMissingProperty
};"}

