const { createDebugHelper } = require('./ko-debug');

// Define a sample ViewModel with the required properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

const debugHelper = createDebugHelper(sampleViewModel);

let passed = 0;
let failed = 0;

function runTest(testName, actual, expected) {
  if (JSON.stringify(actual) === JSON.stringify(expected)) {
    console.log(`PASS: ${testName}`);
    passed++;
  } else {
    console.log(`FAIL: ${testName}`);
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
    failed++;
  }
}

// Test 1: Diagnose missing property "item" (should suggest "items")
console.log('\n--- KnockoutJS Binding Error Debugger Tests ---\n');

const result1 = debugHelper.diagnoseMissingProperty('item');
runTest(
  'Diagnose missing property "item" (should suggest "items")',
  result1.suggestion,
  'items'
);

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
const result2 = debugHelper.diagnoseMissingProperty('selctedItem');
runTest(
  'Diagnose missing property "selctedItem" (should suggest "selectedItem")',
  result2.suggestion,
  'selectedItem'
);

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
const result3 = debugHelper.diagnoseMissingProperty('completelyWrong');
runTest(
  'Diagnose missing property "completelyWrong" (should have null suggestion)',
  result3.suggestion,
  null
);

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
const result4 = debugHelper.diagnoseMissingProperty('isLoad');
runTest(
  'Diagnose missing property "isLoad" (should suggest "isLoading")',
  result4.suggestion,
  'isLoading'
);

// Additional structural checks
const result4check = debugHelper.diagnoseMissingProperty('testProp');
runTest(
  'Result structure is correct',
  {
    error: result4check.error,
    missingProperty: result4check.missingProperty,
    availableProperties: result4check.availableProperties,
    suggestion: result4check.suggestion
  },
  {
    error: true,
    missingProperty: 'testProp',
    availableProperties: ['filterText', 'items', 'isLoading', 'selectedItem', 'totalCount'],
    suggestion: null
  }
);

// Print summary
console.log(`\n--- Results: ${passed} passed, ${failed} failed ---`);

if (failed > 0) {
  process.exit(1);
}
